public struct PairInfo {
    public var host: String
    public var port: UInt16
    public var publicKey: Data
    public var token: Data
    public var name: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(host: String, port: UInt16, publicKey: Data, token: Data, name: String) {
        self.host = host
        self.port = port
        self.publicKey = publicKey
        self.token = token
        self.name = name
    }
}

#if compiler(>=6)
extension PairInfo: Sendable {}
#endif


extension PairInfo: Equatable, Hashable {
    public static func ==(lhs: PairInfo, rhs: PairInfo) -> Bool {
        if lhs.host != rhs.host {
            return false
        }
        if lhs.port != rhs.port {
            return false
        }
        if lhs.publicKey != rhs.publicKey {
            return false
        }
        if lhs.token != rhs.token {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(host)
        hasher.combine(port)
        hasher.combine(publicKey)
        hasher.combine(token)
        hasher.combine(name)
    }
}



