public enum LinkError: Swift.Error {

    
    
    case Handshake(msg: String
    )
    case Crypto(msg: String
    )
    case Format(msg: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLinkError: FfiConverterRustBuffer {
    typealias SwiftType = LinkError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LinkError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Handshake(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Crypto(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Format(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LinkError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Handshake(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Crypto(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Format(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLinkError_lift(_ buf: RustBuffer) throws -> LinkError {
    return try FfiConverterTypeLinkError.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLinkError_lower(_ value: LinkError) -> RustBuffer {
    return FfiConverterTypeLinkError.lower(value)
}


