private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 29
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_apnum_link_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_apnum_link_checksum_func_fingerprint() != 17237) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_func_generate_keypair() != 35508) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_func_make_pair_uri() != 10017) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_func_pairing_code() != 1517) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_func_pairing_token() != 54023) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_func_parse_pair_uri() != 6182) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_func_public_key_for() != 50258) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_func_safety_number() != 37973) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_method_handshake_handshake_hash() != 26271) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_method_handshake_into_session() != 3068) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_method_handshake_is_finished() != 53047) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_method_handshake_read_message() != 16120) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_method_handshake_remote_public_key() != 23812) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_method_handshake_write_message() != 1834) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_method_session_open() != 56708) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_method_session_seal() != 16817) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_constructor_handshake_initiator() != 19911) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_apnum_link_checksum_constructor_handshake_responder() != 41822) {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureApnumLinkInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

